class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n, m = len(str1), len(str2)
        L = n + m - 1
        res = ['?'] * L
        fixed = [False] * L

        # Place T substrings
        for i, c in enumerate(str1):
            if c == 'T':
                for k in range(m):
                    pos = i + k
                    if res[pos] != '?' and res[pos] != str2[k]:
                        return ""
                    res[pos] = str2[k]
                    fixed[pos] = True

        # Fill remaining with 'a'
        for i in range(L):
            if res[i] == '?':
                res[i] = 'a'

        res = ''.join(res)

        # Resolve F substrings
        res_list = list(res)
        while True:
            changed = False
            for j, c in enumerate(str1):
                if c == 'F':
                    seg = res_list[j:j+m]
                    if ''.join(seg) == str2:
                        # find first non-fixed position in this segment
                        idx = -1
                        for k in range(m):
                            pos = j + k
                            if not fixed[pos]:
                                idx = pos
                                break
                        if idx == -1:
                            return ""
                        # change to smallest char != str2[idx - j]
                        desired = str2[idx - j]
                        for ch in "abcdefghijklmnopqrstuvwxyz":
                            if ch != desired:
                                res_list[idx] = ch
                                break
                        changed = True
                        break
            if not changed:
                break
            res_list = res_list  # continue loop

        return ''.join(res_list)
