from typing import List, Tuple, Dict

class Solution:
    def longestSpecialPath(self, edges: List[List[int]], nums: List[int]) -> List[int]:
        n = len(nums)
        g = [[] for _ in range(n)]
        for u, v, w in edges:
            g[u].append((v, w))
            g[v].append((u, w))

        best_len = 0
        best_cnt = 0

        def dfs(u: int, p: int) -> Dict[int, Tuple[int, int]]:
            nonlocal best_len, best_cnt
            mp: Dict[int, Tuple[int, int]] = {nums[u]: (0, 1)}
            for v, w in g[u]:
                if v == p:
                    continue
                child_map = dfs(v, u)
                for val, (dist, nodes) in child_map.items():
                    if val == nums[u]:
                        continue
                    nd = dist + w
                    nn = nodes + 1
                    if val in mp:
                        curd, curn = mp[val]
                        if nd > curd or (nd == curd and nn < curn):
                            mp[val] = (nd, nn)
                    else:
                        mp[val] = (nd, nn)
            # update global best
            for dist, nodes in mp.values():
                if dist > best_len or (dist == best_len and (best_len==0 or nodes < best_cnt)):
                    best_len = dist
                    best_cnt = nodes
            return mp

        dfs(0, -1)
        if best_len == 0:
            return [0, 1]
        return [best_len, best_cnt]
