def solve():
    input = sys.stdin.readline
    N, K = map(int, input().split())
    A = list(map(int, input().split()))
    B = list(map(int, input().split()))
    C = list(map(int, input().split()))
    # If N is small, brute force all values
    if N <= 200:
        vals = []
        for ai in A:
            for bj in B:
                for ck in C:
                    vals.append(ai*bj + bj*ck + ck*ai)
        vals.sort(reverse=True)
        print(vals[K-1])
        return
    # For large N, use a min-heap of size K to keep top K values
    # Iterate over all combinations in a clever way: we sort B descending
    # and for each (i,k) we only consider the largest few B's.
    B_sorted = sorted(B, reverse=True)
    # Choose top M B's such that M^2 >= K
    M = int((K ** 0.5) + 2)
    if M > N:
        M = N
    B_top = B_sorted[:M]
    heap = []
    for ai in A:
        for ck in C:
            for bj in B_top:
                val = ai*bj + bj*ck + ck*ai
                if len(heap) < K:
                    heapq.heappush(heap, val)
                else:
                    if val > heap[0]:
                        heapq.heapreplace(heap, val)
    print(heap[0])

