from typing import List
from functools import lru_cache

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        odds = [i for i in range(1, n+1) if i%2==1]
        evens = [i for i in range(1, n+1) if i%2==0]
        total_odds, total_evens = len(odds), len(evens)

        @lru_cache(maxsize=None)
        def f(o, e, last):
            if o+e == 0:
                return 1
            if last == 1:  # last was odd, next must be even
                if e == 0:
                    return 0
                return e * f(o, e-1, 0)
            else:  # last was even, next must be odd
                if o == 0:
                    return 0
                return o * f(o-1, e, 1)

        result = []
        used = [False]*(n+1)
        curr_k = k
        last_parity = None  # None for first element

        for pos in range(n):
            candidates = []
            for num in range(1, n+1):
                if not used[num]:
                    if last_parity is None or (num%2 != last_parity):
                        candidates.append(num)
            candidates.sort()
            found = False
            for cand in candidates:
                if last_parity is None:
                    # choose cand, determine remaining counts
                    o_rem = total_odds - (cand%2==1)
                    e_rem = total_evens - (cand%2==0)
                    # after choosing, next must be opposite parity
                    cnt = f(o_rem, e_rem, cand%2)
                else:
                    # need to ensure parity matches
                    if cand%2 == last_parity:
                        continue
                    o_rem = total_odds - (cand%2==1)
                    e_rem = total_evens - (cand%2==0)
                    cnt = f(o_rem, e_rem, cand%2)
                if curr_k > cnt:
                    curr_k -= cnt
                else:
                    result.append(cand)
                    used[cand] = True
                    last_parity = cand%2
                    found = True
                    break
            if not found:
                return []
        return result
