class Solution:
    def maxDistance(self, side: int, points: list[list[int]], k: int) -> int:
        n = len(points)
        xs = [p[0] for p in points]
        ys = [p[1] for p in points]

        def check(d: int) -> bool:
            chosen = []

            def dfs(start: int) -> bool:
                if len(chosen) == k:
                    return True
                # pruning: not enough points left
                if n - start < k - len(chosen):
                    return False
                for i in range(start, n):
                    ok = True
                    for j in chosen:
                        if abs(xs[i] - xs[j]) + abs(ys[i] - ys[j]) < d:
                            ok = False
                            break
                    if not ok:
                        continue
                    chosen.append(i)
                    if dfs(i + 1):
                        return True
                    chosen.pop()
                return False

            return dfs(0)

        lo, hi = 0, 2 * side
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if check(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo
