class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        from functools import lru_cache
        n = len(points)
        # Precompute Manhattan distances
        dist = [[0]*n for _ in range(n)]
        for i in range(n):
            xi, yi = points[i]
            for j in range(i+1, n):
                xj, yj = points[j]
                d = abs(xi - xj) + abs(yi - yj)
                dist[i][j] = dist[j][i] = d

        def feasible(dmin: int) -> bool:
            # build adjacency bitmask: edge if distance < dmin
            neigh = [0]*n
            for i in range(n):
                m = 0
                for j in range(n):
                    if i != j and dist[i][j] < dmin:
                        m |= 1 << j
                neigh[i] = m

            @lru_cache(maxsize=None)
            def dp(mask: int) -> int:
                if mask == 0:
                    return 0
                # pick lowest set bit
                v = (mask & -mask).bit_length() - 1
                # option 1: exclude v
                res = dp(mask & ~(1 << v))
                # option 2: include v, remove its neighbors
                res = max(res, 1 + dp(mask & ~((1 << v) | neigh[v])))
                return res

            return dp((1 << n) - 1) >= k

        low, high = 0, 2 * side
        while low < high:
            mid = (low + high + 1) // 2
            if feasible(mid):
                low = mid
            else:
                high = mid - 1
        return low
