class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        n = len(points)
        # Precompute Manhattan distances
        def build_graph(d):
            neigh = [set() for _ in range(n)]
            for i in range(n):
                xi, yi = points[i]
                for j in range(i + 1, n):
                    xj, yj = points[j]
                    if abs(xi - xj) + abs(yi - yj) < d:
                        neigh[i].add(j)
                        neigh[j].add(i)
            return neigh

        def can(d):
            neigh = build_graph(d)
            # Order indices by degree ascending
            order = sorted(range(n), key=lambda x: len(neigh[x]))
            # Recursive backtracking
            def dfs(start, chosen):
                if len(chosen) == k:
                    return True
                # pruning: not enough remaining
                if start >= n:
                    return False
                for idx in range(start, n):
                    v = order[idx]
                    # check conflict
                    conflict = False
                    for c in chosen:
                        if v in neigh[c]:
                            conflict = True
                            break
                    if conflict:
                        continue
                    # choose v
                    chosen.append(v)
                    if dfs(idx + 1, chosen):
                        return True
                    chosen.pop()
                return False
            return dfs(0, [])

        # Binary search over possible distances
        lo, hi = 0, 2 * side  # max possible Manhattan distance
        ans = 0
        while lo <= hi:
            mid = (lo + hi) // 2
            if can(mid):
                ans = mid
                lo = mid + 1
            else:
                hi = mid - 1
        return ans
