from typing import List

class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        n = len(points)
        # precompute all pairwise distances
        dist = [[0]*n for _ in range(n)]
        for i in range(n):
            xi, yi = points[i]
            for j in range(i+1, n):
                xj, yj = points[j]
                d = abs(xi-xj)+abs(yi-yj)
                dist[i][j] = dist[j][i] = d

        def can(d):
            conflict = [[False]*n for _ in range(n)]
            for i in range(n):
                for j in range(i+1, n):
                    if dist[i][j] < d:
                        conflict[i][j] = conflict[j][i] = True

            selected = []

            def dfs(start):
                if len(selected) >= k:
                    return True
                if start == n:
                    return False
                # pruning: if not enough remaining
                if len(selected) + (n - start) < k:
                    return False
                # try include points[start]
                ok = True
                for s in selected:
                    if conflict[s][start]:
                        ok = False
                        break
                if ok:
                    selected.append(start)
                    if dfs(start+1):
                        return True
                    selected.pop()
                # skip this point
                return dfs(start+1)

            return dfs(0)

        lo, hi = 0, 2*side
        ans = 0
        while lo <= hi:
            mid = (lo+hi)//2
            if can(mid):
                ans = mid
                lo = mid+1
            else:
                hi = mid-1
        return ans
