import sys

def mat_mul(A, B, mod):
    n = len(A)
    res = [[0]*n for _ in range(n)]
    for i in range(n):
        Ai = A[i]
        for k in range(n):
            aik = Ai[k]
            if aik == 0:
                continue
            Bk = B[k]
            for j in range(n):
                res[i][j] = (res[i][j] + aik * Bk[j]) % mod
    return res

def mat_pow(mat, exp, mod):
    n = len(mat)
    res = [[0]*n for _ in range(n)]
    for i in range(n):
        res[i][i] = 1
    base = mat
    while exp:
        if exp & 1:
            res = mat_mul(res, base, mod)
        base = mat_mul(base, base, mod)
        exp >>= 1
    return res

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    p = int(next(it))
    A = []
    K = 0
    for i in range(N):
        row = []
        for j in range(N):
            v = int(next(it))
            if v == 0:
                K += 1
            row.append(v % p)
        A.append(row)
    M = mat_pow(A, p, p)
    sign = -1 if K % 2 else 1
    for i in range(N):
        print(' '.join(str((sign * M[i][j]) % p) for j in range(N)))

if __name__ == "__main__":
    solve()
