        n = len(nums)
        pref_nums = [0]*(n+1)
        pref_cost = [0]*(n+1)
        for i in range(n):
            pref_nums[i+1] = pref_nums[i] + nums[i]
            pref_cost[i+1] = pref_cost[i] + cost[i]
        INF = 10**18
        # dp[i][t] = min cost for first i elements using t subarrays
        dp = [[INF]*(n+1) for _ in range(n+1)]
        dp[0][0] = 0
        for i in range(1, n+1):
            for t in range(1, i+1):
                best = INF
                for j in range(t-1, i):
                    sub_nums = pref_nums[i] - pref_nums[j]
                    sub_cost = pref_cost[i] - pref_cost[j]
                    val = dp[j][t-1] + (sub_nums + k*t) * sub_cost
                    if val < best:
                        best = val
                dp[i][t] = best
        return min(dp[n][1:])
