class Solution:
    def minCostGoodCaption(self, caption: str) -> str:
        n = len(caption)
        INF = 10**18
        # dp_forward[i][c][l] minimal cost up to i with char c at i and run length l (1,2,3)
        dp_forward = [[[INF]*3 for _ in range(26)] for _ in range(n)]
        for c in range(26):
            cost = abs(ord(caption[0]) - (ord('a') + c))
            dp_forward[0][c][0] = cost  # l=1 -> index 0
        for i in range(1, n):
            orig = ord(caption[i]) - ord('a')
            # compute minAll and minSame
            minAll = INF
            min_idx = -1
            min2 = INF
            for c in range(26):
                best = min(dp_forward[i-1][c])
                if best < minAll:
                    min2 = minAll
                    minAll = best
                    min_idx = c
                elif best < min2:
                    min2 = best
            for c in range(26):
                cost = abs(orig - c)
                # same char
                bestSame = min(dp_forward[i-1][c])
                lSame = min(bestSame + cost, INF)
                new_l = min(2, 1)  # placeholder
                # update l for same char
                # l' = min(l+1,3) where l was index 0->1,1->2,2->3
                for prev_l in range(3):
                    prev_cost = dp_forward[i-1][c][prev_l]
                    if prev_cost == INF: continue
                    nl = min(prev_l+1,2)
                    new_cost = prev_cost + cost
                    if new_cost < dp_forward[i][c][nl]:
                        dp_forward[i][c][nl] = new_cost
                # different char
                bestDiff = minAll if min_idx != c else min2
                if bestDiff < INF:
                    new_cost = bestDiff + cost
                    if new_cost < dp_forward[i][c][0]:
                        dp_forward[i][c][0] = new_cost
        # compute minimal total cost ensuring final run length >=3
        min_total = INF
        last_c = last_l = None
        for c in range(26):
            for l in range(3):
                if l == 2:  # run length 3
                    cost = dp_forward[n-1][c][l]
                    if cost < min_total:
                        min_total = cost
                        last_c = c
                        last_l = l
        if min_total == INF:
            return ""
        # dp_backward[i][c][l] minimal cost from i to end with char c at i and run length l
        dp_back = [[[INF]*3 for _ in range(26)] for _ in range(n)]
        # last position
        for c in range(26):
            cost = abs(ord(caption[n-1]) - (ord('a') + c))
            dp_back[n-1][c][2] = cost  # run length 3
        # backwards
        for i in range(n-2, -1, -1):
            orig = ord(caption[i]) - ord('a')
            for c in range(26):
                cost = abs(orig - c)
                for l in range(3):
                    # need to consider next char nc
                    best = INF
                    for nc in range(26):
                        for nl in range(3):
                            if dp_back[i+1][nc][nl] == INF: continue
                            if c == nc:
                                expected_l = min(l+1,2)
                                if expected_l != nl: continue
                            else:
                                if nl != 0: continue
                            best = min(best, dp_back[i+1][nc][nl])
                    if best < INF:
                        dp_back[i][c][l] = cost + best
        # reconstruction
        res = []
        cur_l = 0
        for i in range(n):
            orig = ord(caption[i]) - ord('a')
            chosen = None
            for c in range(26):
                cost = abs(orig - c)
                if i == 0:
                    l = 0
                else:
                    if res[-1] == chr(ord('a')+c):
                        l = min(cur_l+1,2)
                    else:
                        l = 0
                if i == n-1 and l != 2: continue
                total = cost + dp_back[i+1][c][l] if i < n-1 else cost
                if total == min_total - sum(abs(ord(caption[j]) - (ord('a') + ord(res[j]))) for j in range(i)):
                    chosen = c
                    cur_l = l
                    break
            if chosen is None:
                return ""
            res.append(chr(ord('a')+chosen))
        return "".join(res)
