            if ch != '-':
                adj[i].append((j, ch))
                adj_dict[i][ch].append(j)

    INF = 10**9
    out_lines = []
    for s in range(N):
        dist = [[INF]*N for _ in range(N)]
        dq = deque()
        # initialize
        for t in range(N):
            if s == t:
                dist[s][t] = 0
                dq.append((s, t))
            else:
                # direct edge s->t
                if t in adj_dict[s]:
                    if 'dummy' not in dist[s][t]:  # dummy check just to avoid syntax
                        pass
                # check if any char from s->t
                for ch in adj_dict[s]:
                    if t in adj_dict[s][ch]:
                        if dist[s][t] > 1:
                            dist[s][t] = 1
                            dq.append((s, t))
                # check reverse
                for ch in adj_dict[t]:
                    if s in adj_dict[t][ch]:
                        if dist[s][t] > 1:
                            dist[s][t] = 1
                            dq.append((s, t))
        # BFS
        while dq:
            u, v = dq.popleft()
            d = dist[u][v]
            # transition via matching chars
            # iterate over chars present in both u and v
            for ch in adj_dict[u]:
                if ch in adj_dict[v]:
                    for u2 in adj_dict[u][ch]:
                        for v2 in adj_dict[v][ch]:
                            if dist[u2][v2] > d + 2:
                                dist[u2][v2] = d + 2
                                dq.append((u2, v2))
        # build output row
        row = []
        for t in range(N):
            val = dist[s][t]
            if val >= INF:
                row.append("-1")
            else:
                row.append(str(val))
