        # we store dist for pairs reachable from (i, j)
        # but we run BFS per j separately
        for j in range(N):
            # BFS from pair (i,j)
            start = (i, j)
            q = deque([start])
            dist = {start:0}
            best = INF
            while q:
                a,b = q.popleft()
                d = dist[(a,b)]
                # meeting at same node
                if a==b:
                    best = min(best, d*2)
                # meeting via edge a->b with same label
                for c in lbl_adj[a]:
                    if b in lbl_adj[a][c]:
                        # there is edge a->b labeled c
