def solve() -> None:
    data = sys.stdin.read().strip().splitlines()
    if not data:
        return
    N = int(data[0])
    grid = data[1:]
    # Build adjacency list for pair graph
    total = N * N
    adj = [[] for _ in range(total)]
    # Precompute edges by label
    edges_by_label = [[[] for _ in range(26)] for _ in range(N)]
    for i in range(N):
        row = grid[i]
        for j, ch in enumerate(row):
            if ch != '-':
                edges_by_label[i][ord(ch)-97].append(j)

    for u in range(N):
        for v in range(N):
            idx = u * N + v
            for c in range(26):
                if not edges_by_label[u][c] or not edges_by_label[v][c]:
                    continue
                for a in edges_by_label[u][c]:
                    for b in edges_by_label[v][c]:
                        adj[idx].append(a * N + b)

    INF = 10**9

    def bfs_multi(sources):
        dist = [INF] * total
        q = deque()
        for s in sources:
            dist[s] = 0
            q.append(s)
        while q:
            cur = q.popleft()
            d = dist[cur]
            for nb in adj[cur]:
                if dist[nb] == INF:
                    dist[nb] = d + 1
                    q.append(nb)
        return dist

    # Sources for even palindrome: (x,x)
    sources_even = [i * N + i for i in range(N)]
    dist_even_pairs = bfs_multi(sources_even)

    # Sources for odd palindrome: pairs (u,v) where edge u->v exists
    sources_odd = []
    for u in range(N):
        row = grid[u]
        for v, ch in enumerate(row):
            if ch != '-':
                sources_odd.append(u * N + v)
    dist_odd_pairs = bfs_multi(sources_odd)

    out_lines = []
    for i in range(N):
        line = []
        for j in range(N):
            if i == j:
                ans = 0
            else:
                even = dist_even_pairs[i * N + j]
                odd = dist_odd_pairs[i * N + j]
                res = INF
                if even != INF:
                    res = min(res, even * 2)
                if odd != INF:
                    res = min(res, odd * 2 + 1)
                ans = -1 if res == INF else res
            line.append(str(ans))
        out_lines.append(' '.join(line))
    sys.stdout.write('\n'.join(out_lines))

if __name__ == "__main__":
