import sys
from collections import defaultdict

def solve():
    H,W = map(int,sys.stdin.readline().split())
    F = [list(map(int,sys.stdin.readline().split())) for _ in range(H)]
    Q = int(sys.stdin.readline())
    queries = []
    for _ in range(Q):
        a,b,y,c,d,z = map(int,sys.stdin.readline().split())
        queries.append((a-1,b-1,y,c-1,d-1,z))
    # Build list of cells sorted by height
    cells = []
    for i in range(H):
        for j in range(W):
            cells.append((F[i][j], i, j))
    cells.sort(reverse=True)
    parent = [i for i in range(H*W)]
    rank = [0]*(H*W)
    active = [False]*(H*W)
    def find(x):
        while parent[x]!=x:
            parent[x]=parent[parent[x]]
            x=parent[x]
        return x
    def union(a,b):
        ra,rb=find(a),find(b)
        if ra==rb: return
        if rank[ra]<rank[rb]:
            parent[ra]=rb
        else:
            parent[rb]=ra
            if rank[ra]==rank[rb]:
                rank[ra]+=1
    # Group queries by threshold = max(Y,Z)
    thresh_queries = defaultdict(list)
    for idx,(a,b,y,c,d,z) in enumerate(queries):
        thresh = max(y,z)
        thresh_queries[thresh].append((idx,a,b,c,d,z,y))
    # Process thresholds descending
    answers = [0]*Q
    curr = 0
    for t in sorted(set([t for t in thresh_queries]), reverse=True):
        while curr < len(cells) and cells[curr][0] >= t:
            _,i,j = cells[curr]
            id = i*W+j
            active[id]=True
            for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
                ni,nj=i+di,j+dj
                if 0<=ni<H and 0<=nj<W:
                    nid=ni*W+nj
                    if active[nid]:
                        union(id,nid)
            curr+=1
        for idx,a,b,c,d,z,y in thresh_queries[t]:
            if find(a*W+b)==find(c*W+d):
                answers[idx]=abs(y-z)
            else:
                answers[idx]=y-1+z-1
    print("\n".join(map(str,answers)))

if __name__=="__main__":
    solve()
