import sys
from bisect import bisect_left, bisect_right

def solve() -> None:
    input = sys.stdin.readline
    N = int(input())
    contests = [tuple(map(int, input().split())) for _ in range(N)]
    Q = int(input())
    queries = [int(input()) for _ in range(Q)]
    maxX = 500000

    size = maxX + 2
    bit = [0] * (size)

    def bit_add(i: int, v: int) -> None:
        while i < size:
            bit[i] += v
            i += i & -i

    def bit_sum(i: int) -> int:
        s = 0
        while i > 0:
            s += bit[i]
            i -= i & -i
        return s

    def f(x: int) -> int:
        return x + bit_sum(x)

    for L, R in contests:
        # find leftmost X with f(X) >= L
        lo, hi = 1, maxX
        while lo < hi:
            mid = (lo + hi) // 2
            if f(mid) >= L:
                hi = mid
            else:
                lo = mid + 1
        left = lo
        # find rightmost X with f(X) <= R
        lo, hi = 1, maxX
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if f(mid) <= R:
                lo = mid
            else:
                hi = mid - 1
        right = lo
        if left <= right:
            bit_add(left, 1)
            bit_add(right + 1, -1)

    out_lines = []
    for x in queries:
        out_lines.append(str(f(x)))
    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
