import sys
from collections import defaultdict, deque

def solve() -> None:
    it = iter(sys.stdin.read().splitlines())
    N = int(next(it))
    S = next(it).strip()
    T = next(it).strip()
    # mapping from source to target
    mp = {}
    for a, b in zip(S, T):
        if a == b:
            continue
        if a in mp:
            if mp[a] != b:
                print(-1)
                return
        else:
            mp[a] = b
    if not mp:
        print(0)
        return
    # Build graph
    graph = defaultdict(set)
    nodes = set()
    for u, v in mp.items():
        graph[u].add(v)
        nodes.add(u); nodes.add(v)
    # Tarjan SCC
    index = {}
    lowlink = {}
    stack = []
    onstack = set()
    idx = 0
    sccs = []
    def strongconnect(v):
        nonlocal idx
        index[v] = lowlink[v] = idx
        idx += 1
        stack.append(v)
        onstack.add(v)
        for w in graph[v]:
            if w not in index:
                strongconnect(w)
                lowlink[v] = min(lowlink[v], lowlink[w])
            elif w in onstack:
                lowlink[v] = min(lowlink[v], index[w])
        if lowlink[v] == index[v]:
            comp = []
            while True:
                w = stack.pop()
                onstack.remove(w)
                comp.append(w)
                if w == v:
                    break
            sccs.append(comp)
    for v in nodes:
        if v not in index:
            strongconnect(v)
    # count cycles
    cycles = 0
    for comp in sccs:
        if len(comp) > 1:
            cycles += 1
    edges = len(mp)
    print(edges + cycles)

if __name__ == "__main__":
