    for s_char, targets in mapping.items():
        if len(targets) > 1:
            print(-1)
            return

    # Build graph
    adj = [[] for _ in range(26)]
    rev_adj = [[] for _ in range(26)]
    edges = 0
    for s_char, targets in mapping.items():
        s = ord(s_char) - 97
        for t_char in targets:
            t = ord(t_char) - 97
            adj[s].append(t)
            rev_adj[t].append(s)
            edges += 1

    # Kosaraju to find SCCs
    visited = [False] * 26
    order = []

    def dfs(v):
        visited[v] = True
        for to in adj[v]:
            if not visited[to]:
                dfs(to)
        order.append(v)

    for v in range(26):
        if not visited[v]:
            dfs(v)

    comp = [-1] * 26
    def rdfs(v, cl):
        comp[v] = cl
        for to in rev_adj[v]:
            if comp[to] == -1:
                rdfs(to, cl)

    cl = 0
    for v in reversed(order):
        if comp[v] == -1:
            rdfs(v, cl)
            cl += 1

    # Count SCC sizes
    size = [0] * cl
    for v in range(26):
        size[comp[v]] += 1

    cycles = sum(1 for s in size if s > 1)
    ans = edges + cycles
    print(ans)

