def solve() -> None:
    it = iter(sys.stdin.read().strip().split())
    try:
        N = int(next(it))
    except StopIteration:
        return
    A = [int(next(it)) for _ in range(N)]
    B = [int(next(it)) for _ in range(N)]

    known_A = [x for x in A if x != -1]
    known_B = [x for x in B if x != -1]

    # constraints for S
    max_A_unknown = 0
    max_B_unknown = 0
    for a, b in zip(A, B):
        if a == -1 and b != -1:
            max_A_unknown = max(max_A_unknown, b)
        if b == -1 and a != -1:
            max_B_unknown = max(max_B_unknown, a)

    candidates = set()
    if known_A and known_B:
        for a in known_A:
            for b in known_B:
                candidates.add(a + b)
    else:
        # no known-known pair, choose minimal S satisfying constraints
        candidates.add(max(max_A_unknown, max_B_unknown))

    # also consider S from known-known sums
    if not candidates:
        candidates.add(0)

    for S in candidates:
        if S < max(max_A_unknown, max_B_unknown):
            continue
        # check multiset condition
        req_B = Counter()
        for a in known_A:
            req_B[S - a] += 1
        cnt_B = Counter(known_B)
        if req_B != cnt_B:
            continue
        # all good
        print("Yes")
        return
    print("No")

