class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        def count_with_zero(n: int) -> int:
            if n <= 0:
                return 0
            s = str(n)
            total = 0
            for i, ch in enumerate(s):
                digit = int(ch)
                if digit == 0:
                    # all numbers formed by fixing this zero and arbitrary digits after
                    remaining = len(s) - i - 1
                    total += 10 ** remaining
            # subtract numbers counted where leading digit is zero (invalid)
            if s[0] == '0':
                total -= 10 ** (len(s) - 1)
            return total

        def count_single_digit(n: int) -> int:
            return min(max(n, 0), 9)

        def count_beautiful(n: int) -> int:
            if n < 0:
                return 0
            return count_with_zero(n) + count_single_digit(n)

        return count_beautiful(r) - count_beautiful(l - 1)
