            return True
        if i > 0 and bad[i-1][0] <= x <= bad[i-1][1]:
            return True
        return False

    if is_bad(1) or is_bad(N):
        print("No")
        return

    q = collections.deque([1])
    visited = set([1])
    while q:
        x = q.popleft()
        for d in range(A, B + 1):
            nx = x + d
            if nx > N:
                continue
            if nx in visited or is_bad(nx):
                continue
            if nx == N:
                print("Yes")
                return
            visited.add(nx)
            q.append(nx)
    print("No")

