import sys

def solve() -> None:
    it = iter(sys.stdin.read().strip().split())
    N = int(next(it)); M = int(next(it)); A = int(next(it)); B = int(next(it))
    bad = [(int(next(it)), int(next(it))) for _ in range(M)]
    # Build good intervals
    good = []
    prev_end = 0
    for l, r in bad:
        if l - 1 > prev_end:
            good.append((prev_end + 1, l - 1))
        prev_end = r
    if prev_end + 1 <= N:
        good.append((prev_end + 1, N))
    # Initially reachable
    reachable = [(1,1)]
    # Helper to merge intervals
    def merge_intervals(intervals):
        if not intervals:
            return []
        intervals.sort()
        res = [intervals[0]]
        for l, r in intervals[1:]:
            if l <= res[-1][1] + 1:
                res[-1] = (res[-1][0], max(res[-1][1], r))
            else:
                res.append((l, r))
        return res
    # Main loop
    while True:
        # Expand reachable
        expanded = []
        for l, r in reachable:
            new_l = l + A
            new_r = r + B
            if new_l > N:
                continue
            if new_r > N:
                new_r = N
            # intersect with good intervals
            for gl, gr in good:
                if gr < new_l:
                    continue
                if gl > new_r:
                    break
                inter_l = max(new_l, gl)
                inter_r = min(new_r, gr)
                if inter_l <= inter_r:
                    expanded.append((inter_l, inter_r))
        # Merge expanded with reachable
        combined = merge_intervals(reachable + expanded)
        if combined == reachable:
            break
        reachable = combined
    # Check if N reachable
    for l, r in reachable:
        if l <= N <= r:
            print("Yes")
            return
    print("No")

if __name__ == "__main__":
