import sys

MOD = 998244353

def main():
    it = iter(sys.stdin.read().strip().split())
    N = int(next(it))
    K = int(next(it))
    A = [int(next(it)) for _ in range(N)]

    # prefix sums S[0..N]
    S = [0] * (N + 1)
    for i in range(1, N + 1):
        S[i] = (S[i-1] + A[i-1]) % MOD

    # powers of S[i] up to K
    powS = [[0]*(K+1) for _ in range(N+1)]
    for i in range(N+1):
        powS[i][0] = 1
        for t in range(1, K+1):
            powS[i][t] = powS[i][t-1] * S[i] % MOD

    # prefix sums of powers: pref[t][j] = sum_{i=0}^{j-1} S_i^t
    pref = [[0]*(N+1) for _ in range(K+1)]
    for t in range(K+1):
        for j in range(1, N+1):
            pref[t][j] = (pref[t][j-1] + powS[j-1][t]) % MOD

    # binomial coefficients
    C = [[0]*(K+1) for _ in range(K+1)]
    for n in range(K+1):
        C[n][0] = C[n][n] = 1
        for r in range(1, n):
            C[n][r] = (C[n-1][r-1] + C[n-1][r]) % MOD

    ans = 0
    for t in range(K+1):
        coeff = C[K][t] * pow(-1, K-t, MOD) % MOD
        for j in range(1, N+1):
            term = powS[j][t] * pref[K-t][j] % MOD
            ans = (ans + coeff * term) % MOD

    print(ans % MOD)

