    for n in range(K+1):
        C[n][0] = C[n][n] = 1
        for k in range(1,n):
            C[n][k] = (C[n-1][k-1] + C[n-1][k]) % MOD
    # precompute powers of S values
    # powers[i][t] = S[i]^t
    powers = [[1]*(K+1) for _ in range(N+1)]
    for i in range(1,N+1):
        val = S[i]
        for t in range(1,K+1):
            powers[i][t] = powers[i][t-1]*val % MOD
    # prefSum_t[r] = sum_{i=0}^{r-1} S[i]^t
    prefSum = [[0]*(K+1) for _ in range(N+1)]
    for t in range(K+1):
        acc = 0
        for r in range(1,N+1):
            prefSum[r][t] = acc
            acc = (acc + powers[r-1][t]) % MOD
    ans = 0
    for t in range(K+1):
        coeff = C[K][t] * ((-1)**(K-t)) % MOD
        if coeff < 0:
            coeff += MOD
        for r in range(1,N+1):
            ans = (ans + coeff * powers[r][K-t] * prefSum[r][t]) % MOD
    print(ans % MOD)

