def solve():
    it = iter(sys.stdin.read().strip().split())
    N = int(next(it))
    A = [int(next(it)) for _ in range(N-1)]
    # precompute coprime factor pairs
    pairs = []
    for a in A:
        lst = []
        for d in range(1, int(a**0.5)+1):
            if a % d == 0:
                e = a // d
                if math.gcd(d, e) == 1:
                    lst.append((d, e))
                if d != e and math.gcd(e, d) == 1:
                    lst.append((e, d))
        pairs.append(lst)

    dp_count = {}
    dp_sum = {}
    # i=0
    for a,b in pairs[0]:
        key = b
        prod = a % MOD
        dp_count[key] = (dp_count.get(key,0)+1)%MOD
        dp_sum[key] = (dp_sum.get(key,0)+prod)%MOD

    for idx in range(1, N-1):
        new_count = {}
        new_sum = {}
        for b_i, cnt_i in dp_count.items():
            sum_i = dp_sum[b_i]
            for a_next, b_next in pairs[idx]:
                if b_i % a_next != 0:
                    continue
                k_next = b_i // a_next
                prod_mul = (a_next * k_next) % MOD
                new_prod_sum = (sum_i * prod_mul) % MOD
                # number of sequences
                new_cnt = cnt_i
                # add
                new_count[b_next] = (new_count.get(b_next,0)+new_cnt)%MOD
                new_sum[b_next] = (new_sum.get(b_next,0)+new_prod_sum)%MOD
        dp_count, dp_sum = new_count, new_sum

    ans = 0
    for val in dp_sum.values():
        ans = (ans + val) % MOD
    print(ans)

