class Solution:
    def lenOfVDiagonal(self, grid):
        n, m = len(grid), len(grid[0])
        dirs = [(1,1),(1,-1),(-1,-1),(-1,1)]
        # dp0,dp1,dp2 for each direction
        dp0 = [[[0]*m for _ in range(n)] for _ in dirs]
        dp1 = [[[0]*m for _ in range(n)] for _ in dirs]
        dp2 = [[[0]*m for _ in range(n)] for _ in dirs]
        for d_idx,(dr,dc) in enumerate(dirs):
            for i in range(n-1,-1,-1):
                for j in range(m-1,-1,-1):
                    ni,nj=i+dr,j+dc
                    if 0<=ni<n and 0<=nj<m:
                        nxt0, nxt1, nxt2 = dp1[d_idx][ni][nj], dp2[d_idx][ni][nj], dp1[d_idx][ni][nj]
                    else:
                        nxt0=nxt1=nxt2=0
                    val=grid[i][j]
                    if val==1:
                        dp0[d_idx][i][j]=1+nxt0
                    else:
                        dp0[d_idx][i][j]=0
                    if val==2:
                        dp1[d_idx][i][j]=1+nxt1
                    else:
                        dp1[d_idx][i][j]=0
                    if val==0:
                        dp2[d_idx][i][j]=1+nxt2
                    else:
                        dp2[d_idx][i][j]=0
        best=0
        for i in range(n):
            for j in range(m):
                if grid[i][j]!=1: continue
                for d_idx,(dr,dc) in enumerate(dirs):
                    # traverse straight
                    ci, cj = i, j
                    step=0
                    while 0<=ci<n and 0<=cj<m:
                        if step==0:
                            if grid[ci][cj]!=1: break
                        else:
                            if step%2==1:
                                if grid[ci][cj]!=2: break
                            else:
                                if grid[ci][cj]!=0: break
                        # update best without turn
                        best=max(best, step+1)
                        # try turn at next cell
                        if step>0:
                            nd_idx=(d_idx+1)%4
                            ni,nj=ci+dirs[nd_idx][0], cj+dirs[nd_idx][1]
                            if 0<=ni<n and 0<=nj<m:
                                # next step index
                                nxt_step=step+1
                                if nxt_step%2==1:
                                    val=dp1[nd_idx][ni][nj]
                                else:
                                    val=dp2[nd_idx][ni][nj]
                                best=max(best, step+1+val)
                        ci+=dr; cj+=dc; step+=1
        return best
