        # forward and backward dp arrays
        fwd = [[[0]*m for _ in range(n)] for _ in range(4)]
        bwd = [[[0]*m for _ in range(n)] for _ in range(4)]
        # compute forward
        for d, (dy,dx) in enumerate(dirs):
            # order depends on direction
            if dy==1:
                rows = range(n)
            else:
                rows = range(n-1,-1,-1)
            if dx==1:
                cols = range(m)
            else:
                cols = range(m-1,-1,-1)
            for i in rows:
                for j in cols:
                    val = grid[i][j]
                    if val==1:
                        fwd[d][i][j] = 1
                    else:
                        pi, pj = i-dy, j-dx
                        if 0<=pi<n and 0<=pj<m and fwd[d][pi][pj]>0:
                            l = fwd[d][pi][pj]
                            if val == pattern[l % 3]:
                                fwd[d][i][j] = l+1
        # compute backward
        for d, (dy,dx) in enumerate(dirs):
            if dy==1:
                rows = range(n-1,-1,-1)
            else:
                rows = range(n)
            if dx==1:
                cols = range(m-1,-1,-1)
            else:
                cols = range(m)
            for i in rows:
                for j in cols:
                    val = grid[i][j]
                    if val==1:
                        bwd[d][i][j] = 1
                    else:
                        ni, nj = i+dy, j+dx
                        if 0<=ni<n and 0<=nj<m and bwd[d][ni][nj]>0:
                            l = bwd[d][ni][nj]
                            if val == pattern[l % 3]:
                                bwd[d][i][j] = l+1
        ans = 0
        for i in range(n):
            for j in range(m):
                if grid[i][j]!=1: continue
                # straight segments
                for d in range(4):
                    ans = max(ans, fwd[d][i][j])
                # V-shaped
                for d in range(4):
                    dn = (d+1)%4
                    a = fwd[d][i][j]
                    b = bwd[dn][i][j]
                    if a>0 and b>0:
                        ans = max(ans, a+b-1)
        return ans
