class Solution:
    def lenOfVDiagonal(self, grid: list[list[int]]) -> int:
        n, m = len(grid), len(grid[0])
        dirs = [(1, 1), (1, -1), (-1, 1), (-1, -1)]
        # dp_no_turn[dir][i][j] and dp_used[dir][i][j]
        dp_no = [[[0] * m for _ in range(n)] for _ in range(4)]
        dp_use = [[[0] * m for _ in range(n)] for _ in range(4)]

        def expected(prev_len: int) -> int:
            if prev_len == 1:
                return 2
            return 2 if prev_len % 2 == 0 else 0

        best = 0
        for i in range(n):
            for j in range(m):
                val = grid[i][j]
                for d in range(4):
                    # start new segment
                    if val == 1:
                        dp_no[d][i][j] = 1
                        best = max(best, 1)
                for d in range(4):
                    dr, dc = dirs[d]
                    pi, pj = i - dr, j - dc
                    if 0 <= pi < n and 0 <= pj < m:
                        # extend no-turn
                        if dp_no[d][pi][pj]:
                            exp_val = expected(dp_no[d][pi][pj])
                            if val == exp_val:
                                dp_no[d][i][j] = max(dp_no[d][i][j], dp_no[d][pi][pj] + 1)
                                best = max(best, dp_no[d][i][j])
                        # extend used-turn (no new turn)
                        if dp_use[d][pi][pj]:
                            exp_val = expected(dp_use[d][pi][pj])
                            if val == exp_val:
                                dp_use[d][i][j] = max(dp_use[d][i][j], dp_use[d][pi][pj] + 1)
                                best = max(best, dp_use[d][i][j])
                        # turn from previous direction
                        prev_d = (d + 3) % 4
                        if dp_no[prev_d][pi][pj]:
                            exp_val = expected(dp_no[prev_d][pi][pj])
                            if val == exp_val:
                                dp_use[d][i][j] = max(dp_use[d][i][j], dp_no[prev_d][pi][pj] + 1)
                                best = max(best, dp_use[d][i][j])
        return best
