        def find(x):
            if parent[x] != x:
                r = find(parent[x])
                parity[x] ^= parity[parent[x]]
                parent[x] = r
            return parent[x]

        def union(x, y, w):
            rx, ry = find(x), find(y)
            px, py = parity[x], parity[y]
            if rx == ry:
                return (px ^ py) == w
            # attach rx under ry
            parent[rx] = ry
            parity[rx] = px ^ py ^ w
            return True

        ok = True
        for x, y, z in edges:
            if not union(x, y, (z>>k)&1):
                ok = False
                break
        if not ok:
            print(-1)
            return

