        rx, ry = find(x), find(y)
        if rx == ry:
            return (xor_val[x] ^ xor_val[y]) == z
        # attach rx under ry
        parent[rx] = ry
        xor_val[rx] = xor_val[x] ^ xor_val[y] ^ z
        return True

    for _ in range(M):
        x, y, z = map(int, input().split())
        if not union(x - 1, y - 1, z):
