    dist = [0] * N
    for i in range(N):
        root = find(i)
        dist[i] = xor_val[i]
        comp_nodes.setdefault(root, []).append(i)

    ans = [0] * N
    for root, nodes in comp_nodes.items():
        sz = len(nodes)
        cnt = [0] * 31
        for v in nodes:
