import sys

class BIT:
    def __init__(self, n):
        self.n = n
        self.bit = [0]*(n+1)
    def add(self, idx, val):
        while idx <= self.n:
            self.bit[idx] += val
            idx += idx&-idx
    def sum(self, idx):
        s = 0
        while idx>0:
            s += self.bit[idx]
            idx -= idx&-idx
        return s
    def kth(self, k):
        idx = 0
        bit_mask = 1 << (self.n.bit_length())
        while bit_mask:
            t = idx + bit_mask
            if t <= self.n and self.bit[t] < k:
                idx = t
                k -= self.bit[t]
            bit_mask >>= 1
        return idx + 1

def main():
