    for i in range(1, n+1):
        bit.add(i,1)
    res = [0]*n
    for i in range(n-1, -1, -1):
        k = P[i]
        pos = bit.kth(k)
        res[pos-1] = i+1
        bit.add(pos,-1)
    print(' '.join(map(str,res)))

if __name__ == "__main__":
    main()
