        ans = 0
        while lo <= hi:
            mid = (lo + hi) // 2
            need = [(mid + p - 1) // p for p in points]  # ceil(mid / p)
            if need[0] == 0:
                need[0] = 1  # must visit index 0 at least once
            max_idx = 0
            total_need = 0
            for i, v in enumerate(need):
                if v > 0:
                    max_idx = i
                total_need += v
            steps = total_need + max_idx - 1  # minimal moves to satisfy needs
            if steps <= m:
                ans = mid
                lo = mid + 1
            else:
                hi = mid - 1
        return ans
