class Solution:
    def longestCommonPrefix(self, words, k):
        from collections import defaultdict
        class Node:
            __slots__ = ("children", "count", "depth")
            def __init__(self, depth):
                self.children = {}
                self.count = 0
                self.depth = depth

        root = Node(0)
        paths = []  # list of node lists for each word
        # Build trie
        for w in words:
            node = root
            path = []
            for ch in w:
                if ch not in node.children:
                    node.children[ch] = Node(node.depth + 1)
                node = node.children[ch]
                node.count += 1
                path.append(node)
            paths.append(path)

        n = len(words)
        ans = [0]*n
        for i in range(n):
            if len(words)-1 < k:
                ans[i] = 0
                continue
            # decrement counts along path of removed word
            for node in paths[i]:
                node.count -= 1
            # find deepest node with count>=k
            max_depth = 0
            stack = [root]
            while stack:
                node = stack.pop()
                if node.count >= k and node.depth > max_depth:
                    max_depth = node.depth
                for child in node.children.values():
                    stack.append(child)
            ans[i] = max_depth
            # restore counts
            for node in paths[i]:
                node.count += 1
        return ans
