class Solution:
    def longestCommonPrefix(self, words, k):
        n = len(words)
        if k > n - 1:
            return [0] * n
        # Build trie
        children = []
        count = []
        depth = []
        children.append({})  # root
        count.append(0)
        depth.append(0)
        max_len = 0
        for w in words:
            node = 0
            count[node] += 1
            max_len = max(max_len, len(w))
            for ch in w:
                if ch not in children[node]:
                    children[node][ch] = len(children)
                    children.append({})
                    count.append(0)
                    depth.append(depth[node] + 1)
                node = children[node][ch]
                count[node] += 1

        # depth_has[depth] = number of nodes at this depth with count >= k
        depth_has = [0] * (max_len + 2)
        for d in range(len(depth)):
            if count[d] >= k:
                depth_has[depth[d]] += 1
        cur_max = max_len
        while cur_max > 0 and depth_has[cur_max] == 0:
            cur_max -= 1

        res = [0] * n
        for i, w in enumerate(words):
            if n - 1 < k:
                res[i] = 0
                continue
            # decrement counts along path
            node = 0
            nodes_path = [node]
            for ch in w:
                node = children[node][ch]
                nodes_path.append(node)
            for node in nodes_path:
                if count[node] == k:
                    depth_has[depth[node]] -= 1
                count[node] -= 1
            while cur_max > 0 and depth_has[cur_max] == 0:
                cur_max -= 1
            res[i] = cur_max

            # restore counts
            for node in nodes_path:
                count[node] += 1
                if count[node] == k:
                    depth_has[depth[node]] += 1
            # restore cur_max if needed
            if cur_max < max_len:
                while cur_max < max_len and depth_has[cur_max + 1] == 0:
                    cur_max += 1
                if depth_has[cur_max + 1] > 0:
                    cur_max += 1
        return res
