                new_cal = cal + c
                ndp = dp[new_cal]
                for (v1,v2), v3 in cur.items():
                    nv1 = min(v1 + (a if v==1 else 0), k)
                    nv2 = min(v2 + (a if v==2 else 0), k)
                    nv3 = min(v3 + (a if v==3 else 0), k)
                    key = (nv1, nv2)
                    cur_val = ndp.get(key)
                    if cur_val is None or nv3 > cur_val:
                        # remove dominated entries
                        # check if existing entry dominates
                        dominated = False
                        to_remove = []
                        for (ev1, ev2), ev3 in ndp.items():
                            if ev1 >= nv1 and ev2 >= nv2 and ev3 >= nv3:
                                dominated = True
                                break
                            if ev1 <= nv1 and ev2 <= nv2 and ev3 <= nv3:
                                to_remove.append((ev1, ev2))
                        if not dominated:
                            for rem in to_remove:
                                del ndp[rem]
                            ndp[key] = nv3
        for cal in range(X+1):
            for (v1,v2), v3 in dp[cal].items():
                if v1 >= k and v2 >= k and v3 >= k:
