    for _ in range(N):
        v = int(next(it))
        a = int(next(it))
        c = int(next(it))
        items.append((v, a, c))

    # Binary search on answer
    lo, hi = 0, sum(a for _, a, _ in items) // 3 + 1
    def can(t: int) -> bool:
        # DP per calorie: list of nondominated states (v1,v2,v3)
        dp = [set() for _ in range(X+1)]
        dp[0].add((0,0,0))
        for v, a, c in items:
            for cal in range(X-c, -1, -1):
                if not dp[cal]:
                    continue
                nc = cal + c
                if nc > X:
                    continue
                new_set = set()
                for (v1,v2,v3) in dp[cal]:
                    nv1, nv2, nv3 = v1, v2, v3
                    if v == 1:
                        nv1 += a
                    elif v == 2:
                        nv2 += a
                    else:
                        nv3 += a
                    new_set.add((nv1, nv2, nv3))
                # Merge and prune dominated
                combined = dp[nc] | new_set
                pruned = set()
                for s in combined:
                    dominated = False
                    for t in combined:
                        if t is s:
                            continue
                        if t[0] >= s[0] and t[1] >= s[1] and t[2] >= s[2] and (t[0] > s[0] or t[1] > s[1] or t[2] > s[2]):
                            dominated = True
                            break
                    if not dominated:
                        pruned.add(s)
                dp[nc] = pruned
        for cal in range(X+1):
            for (v1,v2,v3) in dp[cal]:
                if v1 >= t and v2 >= t and v3 >= t:
                    return True
        return False

    while lo < hi:
        mid = (lo + hi + 1) // 2
        if can(mid):
            lo = mid
        else:
            hi = mid - 1
    print(lo)

if __name__ == "__main__":
    solve()
