from typing import List, Dict

class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        # dp_even: subsequences with even length so far
        # dp_odd: subsequences with odd length so far
        dp_even: Dict[int, int] = {0: 1}  # empty subsequence
        dp_odd: Dict[int, int] = {}
        for num in nums:
            # prepare new dictionaries
            new_even = dp_even.copy()
            new_odd = dp_odd.copy()
            # extend even-length subsequences
            for s, prod in dp_even.items():
                new_prod = prod * num
                if new_prod <= limit:
                    ns = s + num
                    if ns not in new_odd or new_prod > new_odd[ns]:
                        new_odd[ns] = new_prod
            # extend odd-length subsequences
            for s, prod in dp_odd.items():
                new_prod = prod * num
                if new_prod <= limit:
                    ns = s - num
                    if ns not in new_even or new_prod > new_even[ns]:
                        new_even[ns] = new_prod
            dp_even, dp_odd = new_even, new_odd
        ans = -1
        if k in dp_even:
            ans = max(ans, dp_even[k])
        if k in dp_odd:
            ans = max(ans, dp_odd[k])
        return ans
