    def maxProduct(self, nums, k, limit):
        offset = 1800  # enough for sums in [-1800,1800]
        # dp[sum_offset][parity] = max product <= limit
        dp = [[-1, -1] for _ in range(3601)]
        dp[0 + offset][0] = 1  # empty subsequence

        for x in nums:
            new_dp = [row[:] for row in dp]
            for s in range(-offset, offset + 1):
                for p in (0, 1):
                    prod = dp[s + offset][p]
                    if prod == -1:
                        continue
                    # include x
                    new_parity = p ^ 1
                    if p == 0:
                        new_sum = s + x
                    else:
                        new_sum = s - x
                    if abs(new_sum) > offset:
                        continue
                    new_prod = prod * x
                    if new_prod <= limit:
                        if new_prod > new_dp[new_sum + offset][new_parity]:
                            new_dp[new_sum + offset][new_parity] = new_prod
            dp = new_dp

        best = -1
        for p in (0, 1):
            prod = dp[k + offset][p]
            if prod > best:
                best = prod
        return best if best != -1 else -1
