from typing import List, Dict, Set

class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        # dp[parity][sum] = set of achievable products
        dp: List[Dict[int, Set[int]]] = [dict(), dict()]
        dp[0][0] = {1}  # empty subsequence, product placeholder 1

        for num in nums:
            new_dp0 = {s: prods.copy() for s, prods in dp[0].items()}
            new_dp1 = {s: prods.copy() for s, prods in dp[1].items()}

            for parity in (0, 1):
                cur = dp[parity]
                next_parity = parity ^ 1
                for s, prods in cur.items():
                    for p in prods:
                        new_prod = p * num
                        if new_prod > limit:
                            continue
                        new_sum = s + num if parity == 0 else s - num
                        target = new_dp0 if next_parity == 0 else new_dp1
                        if new_sum not in target:
                            target[new_sum] = {new_prod}
                        else:
                            target[new_sum].add(new_prod)

            dp[0], dp[1] = new_dp0, new_dp1

        best = -1
        for parity in (0, 1):
            for prod in dp[parity].get(k, set()):
                if prod > 1 and prod <= limit:  # prod==1 corresponds to empty subsequence
                    best = max(best, prod)
        return best if best != -1 else -1
