class Solution:
    def maxProduct(self, nums: list[int], k: int, limit: int) -> int:
        # dp: dict of (sum, parity) -> max product
        dp = {}
        for x in nums:
            newdp = dict(dp)  # copy current states
            # start new subsequence with x
            if x <= limit:
                newdp[(x, 1)] = max(newdp.get((x, 1), -1), x)
            for (s, parity), prod in dp.items():
                if prod == -1:
                    continue
                newprod = prod * x
                if newprod > limit:
                    continue
                # parity indicates current length parity before adding
                newparity = parity ^ 1
                if parity == 0:
                    newsum = s + x  # even index -> add
                else:
                    newsum = s - x  # odd index -> subtract
                key = (newsum, newparity)
                if newprod > newdp.get(key, -1):
                    newdp[key] = newprod
            dp = newdp
        best = -1
        for (s, _), prod in dp.items():
            if s == k and prod > best:
                best = prod
        return best
