from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        total_subarrays = n * (n + 1) // 2
        total_forbidden = 0
        max_removed = 0
        for a, b in conflictingPairs:
            if a > b:
                a, b = b, a
            forbidden = a * (n - b + 1)
            total_forbidden += forbidden
            if forbidden > max_removed:
                max_removed = forbidden
        return total_subarrays - total_forbidden + max_removed
