import sys, heapq

def solve() -> None:
    it = iter(sys.stdin.read().strip().split())
    try:
        N = int(next(it)); M = int(next(it)); X = int(next(it))
    except StopIteration:
        return
    g = [[] for _ in range(N+1)]
    rg = [[] for _ in range(N+1)]
    for _ in range(M):
        u = int(next(it)); v = int(next(it))
        g[u].append(v)
        rg[v].append(u)

    INF = 10**30
    dist = [[INF, INF] for _ in range(N+1)]
    dist[1][0] = 0
    pq = [(0, 1, 0)]  # cost, node, orientation
    while pq:
        d, v, ori = heapq.heappop(pq)
        if d != dist[v][ori]:
            continue
        # move
        if ori == 0:
            for to in g[v]:
                nd = d + 1
                if nd < dist[to][ori]:
                    dist[to][ori] = nd
                    heapq.heappush(pq, (nd, to, ori))
        else:
            for to in rg[v]:
                nd = d + 1
                if nd < dist[to][ori]:
                    dist[to][ori] = nd
                    heapq.heappush(pq, (nd, to, ori))
        # reverse
        nd = d + X
        if nd < dist[v][1-ori]:
            dist[v][1-ori] = nd
            heapq.heappush(pq, (nd, v, 1-ori))

    ans = min(dist[N][0], dist[N][1])
    print(ans)

if __name__ == "__main__":
    solve()
