class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        # split pattern by '*'
        parts = p.split('*')
        # pattern must have exactly 3 parts
        if len(parts) != 3:
            return -1
        a, b, c = parts[0], parts[1], parts[2]
        n = len(s)
        # helper to find all start indices of pattern part in s
        def kmp_search(pattern):
            m = len(pattern)
            if m == 0:
                return list(range(n+1))  # empty pattern matches at every position
            # build lps
            lps = [0]*m
            k = 0
            for i in range(1, m):
                while k and pattern[k] != pattern[i]:
                    k = lps[k-1]
                if pattern[k] == pattern[i]:
                    k += 1
                lps[i] = k
            # search
            res = []
            k = 0
            for i, ch in enumerate(s):
                while k and pattern[k] != ch:
                    k = lps[k-1]
                if pattern[k] == ch:
                    k += 1
                if k == m:
                    res.append(i - m + 1)
                    k = lps[k-1]
            return res

        starts_a = kmp_search(a)
        starts_b = kmp_search(b)
        starts_c = kmp_search(c)

        INF = 10**9
        # build next arrays
        def build_next(starts, length):
            nxt = [INF]*(n+2)
            idx = 0
            for i in range(n, -1, -1):
                while idx < len(starts) and starts[idx] > i:
                    idx += 1
                if idx < len(starts):
                    nxt[i] = starts[idx]
                else:
                    nxt[i] = INF
            return nxt

        next_a = build_next(starts_a, len(a))
        next_b = build_next(starts_b, len(b))
        next_c = build_next(starts_c, len(c))

        ans = INF
        for pos in starts_a:
            # find b after a
            b_start = next_b[pos + len(a)]
            if b_start == INF:
                continue
            c_start = next_c[b_start + len(b)]
            if c_start == INF:
                continue
            length = c_start + len(c) - pos
            if length < ans:
                ans = length
        return ans if ans != INF else -1
