class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        # split pattern into three parts
        parts = p.split('*')
        pre, mid, suf = parts[0], parts[1], parts[2]
        n = len(s)

        # helper to find all occurrences of a substring
        def find_occurrences(sub):
            if not sub:
                return list(range(n + 1))  # positions for empty string (including end)
            occ = []
            start = s.find(sub, 0)
            while start != -1:
                occ.append(start)
                start = s.find(sub, start + 1)
            return occ

        pre_occ = find_occurrences(pre)
        mid_occ = find_occurrences(mid)
        suf_occ = find_occurrences(suf)

        import bisect

        best = None

        for j in mid_occ:
            # find pre start <= j - len(pre)
            if pre:
                idx = bisect.bisect_right(pre_occ, j - len(pre)) - 1
                if idx < 0:
                    continue
                i = pre_occ[idx]
            else:
                i = j  # empty pre, starts at j

            # find suf start >= j + len(mid)
            if suf:
                idx2 = bisect.bisect_left(suf_occ, j + len(mid))
                if idx2 == len(suf_occ):
                    continue
                k = suf_occ[idx2]
            else:
                k = j + len(mid)  # empty suf, starts immediately after mid

            length = k + len(suf) - i
            if best is None or length < best:
                best = length

        return -1 if best is None else best
