class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        # split p into a,b,c around two '*'
        parts = p.split('*')
        a, b, c = parts[0], parts[1], parts[2]
        n, m = len(s), len(s)

        def kmp_search(text, pattern):
            if pattern == "":
                return list(range(len(text)+1))
            # build lps
            lps = [0] * len(pattern)
            k = 0
            for i in range(1, len(pattern)):
                while k > 0 and pattern[k] != pattern[i]:
                    k = lps[k-1]
                if pattern[k] == pattern[i]:
                    k += 1
                    lps[i] = k
            # search
            res = []
            k = 0
            for i in range(len(text)):
                while k > 0 and pattern[k] != text[i]:
                    k = lps[k-1]
                if pattern[k] == text[i]:
                    k += 1
                if k == len(pattern):
                    res.append(i - len(pattern) + 1)
                    k = lps[k-1]
            return res

        pos_a = kmp_search(s, a)
        pos_b = kmp_search(s, b)
        pos_c = kmp_search(s, c)

        if not pos_a or not pos_b or not pos_c:
            # if any part is empty string, positions are all indices
            if a == "":
                pos_a = list(range(len(s)+1))
            if b == "":
                pos_b = list(range(len(s)+1))
            if c == "":
                pos_c = list(range(len(s)+1))
            # still need to check if any part missing
            if not pos_a or not pos_b or not pos_c:
                return -1

        import bisect
        INF = 10**18
        best = INF
        for i in pos_a:
            # find first b index >= i+len(a)
            j_req = i + len(a)
            idx_b = bisect.bisect_left(pos_b, j_req)
            if idx_b == len(pos_b):
                continue
            j = pos_b[idx_b]
            k_req = j + len(b)
            idx_c = bisect.bisect_left(pos_c, k_req)
            if idx_c == len(pos_c):
                continue
            k = pos_c[idx_c]
            length = k + len(c) - i
            if length < best:
                best = length
        return -1 if best == INF else best
